using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using Htt.Host.Api;
using Htt.Host.Api.Sales;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class TieredIncentiveTests:IAsyncLifetime
{
 readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();static JsonElement E(object x)=>JsonSerializer.SerializeToElement(x,ApiJson.Options);
 async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 sealed record Context(Guid Program,Guid Policy,Guid Period,Guid Invoice,Guid InvoiceLine,Guid Charge,Guid Liability,Guid Clearing,SalesData Sales,string Approver);
 async Task<Context> SetupIncentive(HttpClient c,string formula="PERCENT_NET",decimal value=10,string mode="CLEARING",string basis="NON_CASH",string tierMode="WHOLE_AMOUNT",string window="INVOICE",decimal threshold=200)
 {
 await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var product=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(product.GetProperty("sku").GetString()!,"Commission service",product.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);
 var q=await Submitted(c,d.Draft(3)with{Lines=[new(d.BoxUnit,Quantity:3,UnitPrice:100)]});var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var ol=Id((await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0]);var inv=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{order}/invoices",new InvoiceInput([new(ol,3)],"Done"),1),HttpStatusCode.Created);
 var charge=Guid.NewGuid();var liability=Guid.NewGuid();var clearing=Guid.NewGuid();foreach(var(a,kind)in new[]{(charge,"EXPENSE"),(liability,"LIABILITY"),(clearing,"LIABILITY")})await S("INSERT INTO accounting.accounts(company_id,id,code,name,kind)VALUES(@c,@id,@code,'C08 test',@kind)",("c",db.Company),("id",a),("code",Code()),("kind",kind));
 var approver=await Staff(db,"FINANCE");var today=await Today();var program=await Create(c,"/incentives/programs",new IncentiveProgramInput(mode=="CUSTOMER_CREDIT"?"REBATE":"COMMISSION","Approved test",mode=="CUSTOMER_CREDIT"?d.Customer:null,mode=="CUSTOMER_CREDIT"?null:db.Actor));var period=await Create(c,"/incentives/periods",new IncentivePeriodInput(today,today.AddDays(1)));Guid? supplier=mode=="SUPPLIER_BILL"?await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Commission contractor",null)):null;Guid? taxCode=mode=="SUPPLIER_BILL"?(await Get(c,"/foundation")).GetProperty("taxCodes").EnumerateArray().Single(t=>t.GetProperty("code").GetString()=="GST").GetProperty("id").GetGuid():null;var config=new{supplierId=supplier,taxCodeId=taxCode,basis="NET_SALES",formula,value,expenseAccountId=charge,liabilityAccountId=liability,settlementMode=mode,clearingAccountId=mode=="CLEARING"?(Guid?)clearing:null,taxTreatment=mode=="CLEARING"?"EXTERNAL_PAYROLL":mode=="SUPPLIER_BILL"?"CONTRACTOR_SERVICE":"PRICE_REDUCTION",taxReviewReference="Reviewed test contract",deductRebates=true,retroactiveAcknowledged=true,recoverableGst=mode=="SUPPLIER_BILL",baseUomId=formula=="FIXED_PER_BASE_UNIT"?await S("SELECT base_uom_id FROM catalog.products WHERE company_id=@c AND id=@p",("c",db.Company),("p",d.Product)):null};
 var tier=JsonNode.Parse(E(config).GetRawText())!;tier["formula"]="TIER_PERCENT_NET";tier.AsObject().Remove("value");tier["tierMode"]=tierMode;tier["thresholdUnit"]="AUD_NET";tier["window"]=window;tier["tiers"]=JsonSerializer.SerializeToNode(new[]{new{from=0m,rate=5m},new{from=threshold,rate=10m}});if(window=="FIXED_WINDOW"){tier["windowFrom"]=today.ToString("yyyy-MM-dd");tier["windowTo"]=today.AddDays(1).ToString("yyyy-MM-dd");}
 var policy=await Create(c,$"/incentives/programs/{program}/policies",new IncentivePolicyInput(0,today,today.AddDays(1),E(tier)));await using var api=new TestApi(db);using var f=api.Authenticated(approver.Subject);await Expect(await Send(f,HttpMethod.Post,$"/incentives/policies/{policy}/approve",new IncentiveReviewInput("Independent contract review")),HttpStatusCode.OK);return new(program,policy,period,Id(inv),Id(inv.GetProperty("lines")[0]),charge,liability,clearing,d,approver.Subject);
 }
 async Task<JsonElement> Run(HttpClient c,Context x,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,"/incentives/runs",new IncentiveRunInput(x.Program,x.Period,await Today(),await Today(),"Accrue",[x.Invoice]),key:key),HttpStatusCode.Created);
 async Task<JsonElement> ApproveRun(HttpClient f,JsonElement r,string? key=null)=>await Expect(await Send(f,HttpMethod.Post,$"/incentives/runs/{Id(r)}/approve",version:1,key:key),HttpStatusCode.OK);
 async Task<Guid> Claim()=> (Guid)(await S("SELECT id FROM incentives.claims WHERE company_id=@c ORDER BY created_at LIMIT 1",("c",db.Company)))!;
 async Task<decimal> Balance(Guid claim)=>(decimal)(await S("SELECT incentives.claim_balance(@id)",("id",claim)))!;
 Task<HttpResponseMessage> Credit(HttpClient c,Context x,decimal net,decimal tax=0)=>Send(c,HttpMethod.Post,$"/sales-invoices/{x.Invoice}/amount-credit-notes",new AmountCreditInput("Price adjustment",[new(x.InvoiceLine,net,tax,"Source adjustment")]));
 
 [Theory][InlineData("WHOLE_AMOUNT",30)][InlineData("PROGRESSIVE",20)]
 public async Task Explicit_tiers_accrue_and_recover_on_credit_with_GL_reconciliation(string tierMode,decimal expected)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,tierMode:tierMode);using var f=api.Authenticated(x.Approver);var r=await Run(c,x);Assert.Equal(expected,D(r.GetProperty("plan").GetProperty("lines")[0].GetProperty("target")));await ApproveRun(f,r);await Expect(await Credit(c,x,150,15),HttpStatusCode.Created);await ApproveRun(f,await Run(c,x));Assert.Equal(7.5m,await Balance(await Claim()));Assert.Equal(0L,await S("SELECT count(*)FROM incentives.control_balances()WHERE expected<>actual"));await FinancialReportAssertions.Check(c);}
 [Theory][InlineData("WHOLE_AMOUNT",199.99,10)][InlineData("WHOLE_AMOUNT",200,20)][InlineData("WHOLE_AMOUNT",200.01,20)][InlineData("PROGRESSIVE",199.99,10)][InlineData("PROGRESSIVE",200,10)][InlineData("PROGRESSIVE",200.01,10)][InlineData("PROGRESSIVE",300,20)][InlineData("WHOLE_AMOUNT",0,0)]
 public async Task Threshold_boundaries_and_final_cent_rounding_are_explicit(string algorithm,decimal amount,decimal expected)
 {var config=E(new{tierMode=algorithm,tiers=new[]{new{from=0m,rate=5m},new{from=200m,rate=10m}}});Assert.Equal(expected,(decimal)(await S("SELECT incentives.tier_amount(@f::jsonb,@n)",("f",config.GetRawText()),("n",amount)))!);}
 async Task<Guid> AdditionalInvoice(HttpClient c,Context x)
 {var q=await Submitted(c,x.Sales.Draft(3)with{Lines=[new(x.Sales.BoxUnit,Quantity:3,UnitPrice:100)]});var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var line=Id((await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0]);return Id(await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{order}/invoices",new InvoiceInput([new(line,3)],"Done"),1),HttpStatusCode.Created));}
 [Theory][InlineData("WHOLE_AMOUNT",60)][InlineData("PROGRESSIVE",35)]
 public async Task Fixed_window_expands_subset_and_exact_allocation_reconciles_to_group(string algorithm,decimal expected)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,tierMode:algorithm,window:"FIXED_WINDOW",threshold:500);using var f=api.Authenticated(x.Approver);await AdditionalInvoice(c,x);var r=await Run(c,x);var lines=r.GetProperty("plan").GetProperty("lines").EnumerateArray().ToArray();Assert.Equal(2,lines.Length);Assert.Equal(expected,lines.Sum(l=>D(l.GetProperty("target"))));Assert.All(lines,l=>Assert.Equal(600,D(l.GetProperty("windowEligibleNet"))));await ApproveRun(f,r);Assert.Equal(expected,(decimal)(await S("SELECT sum(delta)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)))!);Assert.Equal(0L,await S("SELECT count(*)FROM incentives.control_balances()WHERE expected<>actual"));}
 [Fact]public async Task New_invoice_between_prepare_and_approve_invalidates_entire_frozen_population()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,window:"FIXED_WINDOW",threshold:500);using var f=api.Authenticated(x.Approver);var r=await Run(c,x);await AdditionalInvoice(c,x);await Expect(await Send(f,HttpMethod.Post,$"/incentives/runs/{Id(r)}/approve",version:1),HttpStatusCode.Conflict);Assert.Equal(0L,await S("SELECT count(*)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Cross_invoice_credit_reprices_entire_window_and_preserves_negative_recovery_after_clearing()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,window:"FIXED_WINDOW",threshold:500);using var f=api.Authenticated(x.Approver);await AdditionalInvoice(c,x);await ApproveRun(f,await Run(c,x));var claim=(Guid)(await S("SELECT id FROM incentives.claims WHERE company_id=@c AND invoice_id=@i",("c",db.Company),("i",x.Invoice)))!;await Expect(await Send(c,HttpMethod.Post,"/incentives/settlements",new IncentiveSettlementInput(claim,30,0,await Today(),Code(),"Transfer","Reviewed external payroll",E(Array.Empty<object>()))),HttpStatusCode.Created);await Expect(await Credit(c,x,150,15),HttpStatusCode.Created);await ApproveRun(f,await Run(c,x));Assert.Equal(-22.5m,await Balance(claim));Assert.Equal(22.5m,(decimal)(await S("SELECT sum(delta)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)))!);Assert.Equal(0L,await S("SELECT count(*)FROM incentives.control_balances()WHERE expected<>actual"));}
 async Task<JsonNode> Config(HttpClient c,Context x)=>JsonNode.Parse((await Get(c,$"/incentives/programs/{x.Program}")).GetProperty("policies")[0].GetProperty("config").GetRawText())!;
 [Theory][InlineData("missingMode")][InlineData("cash")][InlineData("unit")][InlineData("descending")][InlineData("duplicate")][InlineData("missingZero")][InlineData("badRate")][InlineData("extra")][InlineData("value")][InlineData("fractionalThreshold")][InlineData("stringRate")]
 public async Task Ambiguous_or_invalid_tier_policy_is_rejected(string fault)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);var cfg=await Config(c,x);switch(fault){case"missingMode":cfg.AsObject().Remove("tierMode");break;case"cash":cfg["basis"]="CASH_SALES";break;case"unit":cfg["thresholdUnit"]="QUANTITY";break;case"descending":cfg["tiers"]![1]!["rate"]=1;break;case"duplicate":cfg["tiers"]![1]!["from"]=0;break;case"missingZero":cfg["tiers"]![0]!["from"]=1;break;case"badRate":cfg["tiers"]![1]!["rate"]=101;break;case"extra":cfg["tiers"]![0]!["other"]=1;break;case"value":cfg["value"]=10;break;case"fractionalThreshold":cfg["tiers"]![1]!["from"]=200.001m;break;case"stringRate":cfg["tiers"]![1]!["rate"]="10";break;}var today=await Today();await Expect(await Send(c,HttpMethod.Post,$"/incentives/programs/{x.Program}/policies",new IncentivePolicyInput(1,today,today.AddDays(1),E(cfg))),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task Cumulative_window_cannot_overlap_approved_policy_or_silently_change_revision_cohort()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,window:"FIXED_WINDOW");var cfg=await Config(c,x);cfg["tiers"]![1]!["rate"]=12;var today=await Today();await Expect(await Send(c,HttpMethod.Post,$"/incentives/programs/{x.Program}/policies",new IncentivePolicyInput(1,today,today.AddDays(1),E(cfg))),HttpStatusCode.Conflict);}
 [Fact]public async Task Tier_accrual_requires_independent_approver_and_current_permissions()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);var r=await Run(c,x);await Expect(await Send(c,HttpMethod.Post,$"/incentives/runs/{Id(r)}/approve",version:1),HttpStatusCode.Forbidden);var key=Code();await Run(c,x,key);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='incentives.manage'",("c",db.Company));await Expect(await Send(c,HttpMethod.Post,"/incentives/runs",new IncentiveRunInput(x.Program,x.Period,await Today(),await Today(),"Accrue",[x.Invoice]),key:key),HttpStatusCode.Forbidden);}
 [Theory][InlineData(true)][InlineData(false)]
 public async Task Concurrent_tier_approvals_do_not_duplicate_claims_or_accruals(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,window:"FIXED_WINDOW");using var f=api.Authenticated(x.Approver);var key=Code();var first=await Run(c,x);var second=sameKey?first:await Run(c,x);var rs=await Task.WhenAll(Send(f,HttpMethod.Post,$"/incentives/runs/{Id(first)}/approve",version:1,key:key),Send(f,HttpMethod.Post,$"/incentives/runs/{Id(second)}/approve",version:1,key:sameKey?key:Code()));Assert.Equal(sameKey?2:1,rs.Count(z=>z.StatusCode==HttpStatusCode.OK));Assert.Equal(sameKey?0:1,rs.Count(z=>z.StatusCode==HttpStatusCode.Conflict));Assert.Equal(1L,await S("SELECT count(*)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Private_tier_helpers_are_not_direct_app_entrypoints()
 {foreach(var name in new[]{"incentives.validate_policy_before_tiers(uuid,jsonb)","incentives.apply_tiers(jsonb,uuid)","incentives.lock_tier_sources(uuid,uuid)","incentives.tier_amount(jsonb,numeric)"})Assert.False((bool)(await S("SELECT has_function_privilege('htt_app',@f,'EXECUTE')",("f",name)))!);}

 [Fact]public async Task Audit_failure_rolls_back_accrual_and_retry_keeps_single_financial_effect()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);var r=await Run(c,x);var key=Code();await S($"CREATE FUNCTION incentives.test_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='incentives.changed'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER c08_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION incentives.test_fail()");try{await Expect(await Send(f,HttpMethod.Post,$"/incentives/runs/{Id(r)}/approve",version:1,key:key),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM incentives.accruals WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER c08_fail ON platform.audit_events;DROP FUNCTION incentives.test_fail()");}await ApproveRun(f,r,key);Assert.Equal(30,await Balance(await Claim()));}
 [Fact]public async Task Tenant_isolation_rejects_foreign_program_and_run()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var other=api.Authenticated(company:db.OtherCompany);await Expect(await other.GetAsync($"/api/v1/incentives/programs/{x.Program}"),HttpStatusCode.NotFound);await Expect(await Send(other,HttpMethod.Post,"/incentives/runs",new IncentiveRunInput(x.Program,x.Period,await Today(),await Today(),"Foreign")),HttpStatusCode.NotFound);}
 [Fact]public async Task Personal_view_is_own_only_and_does_not_disclose_source_or_cost_policy()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));var own=await Get(c,"/incentives/me");Assert.Single(own.EnumerateArray());Assert.Equal("APPROVED_BALANCE",own[0].GetProperty("state").GetString());var raw=own.GetRawText();Assert.DoesNotContain("invoice",raw,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain(x.Charge.ToString(),raw);var staff=await Staff(db,"SALES",x.Sales);using var other=api.Authenticated(staff.Subject);Assert.Empty((await Get(other,"/incentives/me")).EnumerateArray());}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]public async Task Rebate_credit_is_linked_without_recursive_accrual_and_full_cancellation_zeroes_entitlement(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,mode:"CUSTOMER_CREDIT",basis:basis);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));var claim=await Claim();await Expect(await Send(c,HttpMethod.Post,"/incentives/settlements",new IncentiveSettlementInput(claim,30,3,await Today(),Code(),"Approved rebate","Price rebate contract",E(new[]{new{invoiceLineId=x.InvoiceLine,net=30,tax=3,description="Rebate"}}))),HttpStatusCode.Created);Assert.Equal(0,await Balance(claim));var r=await Run(c,x);Assert.Equal(0,D(r.GetProperty("plan").GetProperty("lines")[0].GetProperty("delta")));await Expect(await Credit(c,x,270,27),HttpStatusCode.Created);await ApproveRun(f,await Run(c,x));Assert.Equal(-30,await Balance(claim));}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Supplier_settlement_reuses_AP_and_purchase_GST_and_recovery_uses_linked_supplier_credit(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c,mode:"SUPPLIER_BILL",basis:basis);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));var claim=await Claim();var paid=await Expect(await Send(c,HttpMethod.Post,"/incentives/settlements",new IncentiveSettlementInput(claim,30,3,await Today(),Code(),"Contractor commission","Tax invoice",E(Array.Empty<object>()))),HttpStatusCode.Created);var bill=paid.GetProperty("underlyingDocumentId").GetGuid();Assert.Equal(33m,(decimal)(await S("SELECT amount FROM accounting.ap_items WHERE company_id=@c AND bill_id=@id",("c",db.Company),("id",bill)))!);await Expect(await Credit(c,x,100,10),HttpStatusCode.Created);await ApproveRun(f,await Run(c,x));Assert.Equal(-10,await Balance(claim));await Expect(await Send(c,HttpMethod.Post,"/incentives/settlements",new IncentiveSettlementInput(claim,-10,-1,await Today(),Code(),"Recovery","Credit evidence",E(Array.Empty<object>()),Id(paid))),HttpStatusCode.Created);Assert.Equal(0,await Balance(claim));await FinancialReportAssertions.Check(c);Assert.Equal("CONSISTENT",(await Get(c,"/accounting/reconciliation")).GetProperty("status").GetString());}
 [Fact]public async Task Invoice_policy_revision_does_not_reprice_pinned_tier_claim()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var x=await SetupIncentive(c);using var f=api.Authenticated(x.Approver);await ApproveRun(f,await Run(c,x));var cfg=await Config(c,x);cfg["tiers"]![1]!["rate"]=20;var policy=await Create(c,$"/incentives/programs/{x.Program}/policies",new IncentivePolicyInput(1,await Today(),(await Today()).AddDays(1),E(cfg)));await Expect(await Send(f,HttpMethod.Post,$"/incentives/policies/{policy}/approve",new IncentiveReviewInput("New revision")),HttpStatusCode.OK);var r=await Run(c,x);Assert.Equal(x.Policy,r.GetProperty("plan").GetProperty("lines")[0].GetProperty("policyId").GetGuid());Assert.Equal(0,D(r.GetProperty("plan").GetProperty("lines")[0].GetProperty("delta")));var next=await AdditionalInvoice(c,x);r=await Run(c,x with{Invoice=next});Assert.Equal(60,D(r.GetProperty("plan").GetProperty("lines")[0].GetProperty("target")));}
